import { useState, useMemo, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { toast } from 'sonner';
import { scopedStorage, logger } from '@lark-apaas/client-toolkit-lite';
import { useAuth } from '@/hooks/useAuth';
// echarts 按需引入，避免全量打 1MB+ 进 chunk
import ReactEChartsCore from 'echarts-for-react/lib/core';
import * as echarts from 'echarts/core';
import { LineChart } from 'echarts/charts';
import {
  GridComponent,
  TooltipComponent,
  LegendComponent,
} from 'echarts/components';
import { CanvasRenderer } from 'echarts/renderers';
import type { EChartsOption } from 'echarts';

echarts.use([LineChart, GridComponent, TooltipComponent, LegendComponent, CanvasRenderer]);
import {
  TrendingUp,
  TrendingDown,
  DollarSign,
  ShoppingCart,
  Eye,
  RefreshCw,
  Plus,
  Trash2,
  AlertTriangle,
  CheckCircle2,
  AlertCircle,
  Users,
  Calendar,
  Target,
} from 'lucide-react';
import type { ThemeConfig } from '@/lib/theme';
import CollapsibleSection from '@/components/CollapsibleSection';
import BusinessSummaryCard from '@/components/BusinessSummaryCard';
import DirectorPromptCard from '@/components/DirectorPromptCard';
import {
  type IKpiDailyRecord,
  type KpiMetrics,
  type KpiStatus,
  type SiteOption,
  calculateKpiMetrics,
  getKpiStatus,
  loadUserRecords,
  addRecord,
  deleteRecord,
  getTodayDate,
  getRecentDays,
  getMonthRange,
  formatDate,
  SITE_OPTIONS,
  DEFAULT_SITE,
} from '@/data/kpi';

function KpiStatusDot({ status, size = 'md' }: { status: KpiStatus; size?: 'sm' | 'md' | 'lg' }) {
  const sizeMap = {
    sm: 'size-2',
    md: 'size-2.5',
    lg: 'size-3',
  };
  const colorClass = status.level === 'green' ? 'bg-green-500'
    : status.level === 'orange' ? 'bg-amber-500'
    : 'bg-red-500';
  return (
    <span className={`inline-block ${sizeMap[size]} rounded-full shrink-0 ${colorClass}`} />
  );
}

function KpiMetricCard({
  label,
  value,
  suffix = '',
  status,
  icon: Icon,
  subLabel,
  theme,
}: {
  label: string;
  value: string | number;
  suffix?: string;
  status: KpiStatus;
  icon: React.ComponentType<{ className?: string }>;
  subLabel?: string;
  theme: ThemeConfig;
}) {
  return (
    <Card
      className="border overflow-hidden"
      style={{
        backgroundColor: theme.ui.glassBg,
        backdropFilter: 'blur(10px) saturate(180%)',
        WebkitBackdropFilter: 'blur(10px) saturate(180%)',
        borderColor: theme.ui.cardBorder,
        boxShadow: theme.ui.glassShadow,
      }}
    >
      <CardContent className="py-4 px-4">
        <div className="flex items-start justify-between gap-2 mb-2">
          <div className="flex items-center gap-2 min-w-0">
            <div
              className="size-8 rounded-md flex items-center justify-center shrink-0"
              style={{ backgroundColor: status.bg }}
            >
              <Icon className="size-4 text-current" />
            </div>
            <span className="text-xs text-muted-foreground truncate">{label}</span>
          </div>
          <div className="flex items-center gap-1 shrink-0">
            <KpiStatusDot status={status} />
            <span className="text-[11px]" style={{ color: status.color }}>
              {status.label}
            </span>
          </div>
        </div>
        <div className="flex items-baseline gap-1">
          <span
            className="text-2xl font-bold tabular-nums tracking-tight"
            style={{ color: status.color }}
          >
            {value}
          </span>
          <span className="text-xs text-muted-foreground">{suffix}</span>
        </div>
        {subLabel && (
          <div className="text-[11px] text-muted-foreground mt-1">{subLabel}</div>
        )}
      </CardContent>
    </Card>
  );
}

interface KpiDashboardSectionProps {
  theme: ThemeConfig;
}

export default function KpiDashboardSection({ theme }: KpiDashboardSectionProps) {
  const { user } = useAuth();
  const username = user?.username || 'guest';
  const nickname = user?.nickname || user?.username || 'guest';

  const [records, setRecords] = useState<IKpiDailyRecord[]>([]);
  const [activeView, setActiveView] = useState<'7d' | '30d'>('7d');
  const [expandedSections, setExpandedSections] = useState<Record<string, boolean>>({
    chart: true,
    form: true,
    list: true,
    director: false,
  });
  const toggleSection = (id: string) => {
    setExpandedSections(prev => ({ ...prev, [id]: !prev[id] }));
  };

  // 表单
  const [formDate, setFormDate] = useState(getTodayDate());
  const [formOrders, setFormOrders] = useState('');
  const [formListings, setFormListings] = useState('');
  const [formAdSpend, setFormAdSpend] = useState('');
  const [formAdSales, setFormAdSales] = useState('');
  const [formVisits, setFormVisits] = useState('');
  const [formRefunds, setFormRefunds] = useState('');
   const [formTotalSales, setFormTotalSales] = useState('');
   const [formNaturalOrders, setFormNaturalOrders] = useState('');
   const [formTotalCost, setFormTotalCost] = useState('');
   const [formSite, setFormSite] = useState(DEFAULT_SITE);
   const currentCurrency =
     SITE_OPTIONS.find(o => o.value === formSite)?.currency || 'USD';
   const [formNote, setFormNote] = useState('');
   const [isSubmitting, setIsSubmitting] = useState(false);

  const refreshRecords = () => {
    const list = loadUserRecords(username);
    setRecords(list);
  };

  useEffect(() => {
    refreshRecords();
  }, []);

  // 今日数据
  const today = getTodayDate();
  const todayRecords = useMemo(() => records.filter(r => r.date === today), [records, today]);
  const todayMetrics = useMemo(() => calculateKpiMetrics(todayRecords), [todayRecords]);
  const todayOrderCount = useMemo(
    () => todayRecords.reduce((s, r) => s + r.orderCount, 0),
    [todayRecords],
  );
  const todayStatus = useMemo(
    () => getKpiStatus(todayMetrics, todayOrderCount),
    [todayMetrics, todayOrderCount],
  );

  // 本月数据
  const monthRange = getMonthRange();
  const monthRecords = useMemo(
    () => records.filter(r => r.date >= monthRange.start && r.date <= monthRange.end),
    [records, monthRange],
  );
  const monthMetrics = useMemo(() => calculateKpiMetrics(monthRecords), [monthRecords]);
   const monthOrderCount = useMemo(
     () => monthRecords.reduce((s, r) => s + r.orderCount, 0),
     [monthRecords],
   );
   const monthAdSpend = useMemo(
     () => monthRecords.reduce((s, r) => s + r.adSpend, 0),
     [monthRecords],
   );
   const monthNaturalOrders = useMemo(
     () => monthRecords.reduce((s, r) => s + (r.naturalOrders || 0), 0),
     [monthRecords],
   );
   const monthStatus = useMemo(
     () => getKpiStatus(monthMetrics, monthOrderCount),
     [monthMetrics, monthOrderCount],
   );
   // 本月统一币种：全部一致则显示该币种，否则显示 "多币种"
   const monthCurrency = useMemo(() => {
     if (monthRecords.length === 0) return 'USD';
     const first = monthRecords[0].currency || 'USD';
     const allSame = monthRecords.every(r => (r.currency || 'USD') === first);
     return allSame ? first : 'MIX';
   }, [monthRecords]);
   // 今日币种
   const todayCurrency = useMemo(() => {
     if (todayRecords.length === 0) return 'USD';
     const first = todayRecords[0].currency || 'USD';
     const allSame = todayRecords.every(r => (r.currency || 'USD') === first);
     return allSame ? first : 'MIX';
   }, [todayRecords]);

  // 近 N 天趋势数据
  const trendDays = activeView === '7d' ? 7 : 30;
  const trendDateList = useMemo(() => getRecentDays(trendDays).reverse(), [trendDays]); // 正序
  const trendData = useMemo(() => {
    return trendDateList.map(date => {
      const dayRecords = records.filter(r => r.date === date);
      const m = calculateKpiMetrics(dayRecords);
      const orders = dayRecords.reduce((s, r) => s + r.orderCount, 0);
      return {
        date,
        orders,
        sales: m.totalSales,
        acos: Number((m.acos * 100).toFixed(1)),
      };
    });
  }, [records, trendDateList]);

  // 趋势图 option
  const chartOption: EChartsOption = useMemo(() => {
    const xData = trendData.map(d => d.date.slice(5)); // MM-DD
    return {
      tooltip: { trigger: 'axis' },
      legend: { type: 'scroll', bottom: 0 },
      grid: { left: '3%', right: '4%', bottom: '18%', containLabel: true },
      xAxis: {
        type: 'category',
        data: xData,
        boundaryGap: false,
      },
      yAxis: [
        {
          type: 'value',
          name: '出单数/销售额',
          position: 'left',
        },
        {
          type: 'value',
          name: 'ACOS(%)',
          position: 'right',
          axisLabel: { formatter: '{value}%' },
        },
      ],
      series: [
        {
          name: '出单数',
          type: 'line',
          data: trendData.map(d => d.orders),
          smooth: true,
          yAxisIndex: 0,
          itemStyle: { color: '#22c55e' },
          areaStyle: {
            color: {
              type: 'linear',
              x: 0, y: 0, x2: 0, y2: 1,
              colorStops: [
                { offset: 0, color: 'rgba(34,197,94,0.25)' },
                { offset: 1, color: 'rgba(34,197,94,0.02)' },
              ],
            },
          },
        },
        {
          name: '广告销售额(USD)',
          type: 'line',
          data: trendData.map(d => d.sales),
          smooth: true,
          yAxisIndex: 0,
          itemStyle: { color: '#3b82f6' },
          areaStyle: {
            color: {
              type: 'linear',
              x: 0, y: 0, x2: 0, y2: 1,
              colorStops: [
                { offset: 0, color: 'rgba(59,130,246,0.2)' },
                { offset: 1, color: 'rgba(59,130,246,0.02)' },
              ],
            },
          },
        },
        {
          name: 'ACOS(%)',
          type: 'line',
          data: trendData.map(d => d.acos),
          smooth: true,
          yAxisIndex: 1,
          itemStyle: { color: '#f59e0b' },
          lineStyle: { type: 'dashed' },
        },
      ],
    };
  }, [trendData]);

  // 提交表单
  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (isSubmitting) return;

    const orderCount = Number(formOrders) || 0;
    const listingCount = Number(formListings) || 0;
    const adSpend = Number(formAdSpend) || 0;
    const adSales = Number(formAdSales) || 0;
    const totalVisits = Number(formVisits) || 0;
    const refundCount = Number(formRefunds) || 0;
     const totalSales = Number(formTotalSales) || 0;
     const naturalOrders = Number(formNaturalOrders) || 0;
     const totalCost = Number(formTotalCost) || 0;
     const siteOption = SITE_OPTIONS.find(s => s.value === formSite) || SITE_OPTIONS[0];

    if (!formDate) {
      toast.error('请选择日期');
      return;
    }

    setIsSubmitting(true);
    try {
      // 读取历史记录保留 costPerUnit（旧数据兼容，不主动修改）
      const all = JSON.parse(JSON.stringify(loadUserRecords(username)));
      const existing = all.find((r: IKpiDailyRecord) => r.date === formDate);
      const costPerUnit = existing?.costPerUnit ?? 0;

      const record: IKpiDailyRecord = {
        id: `${username}-${formDate}-${Date.now()}`,
        date: formDate,
        username,
        nickname,
        orderCount,
        listingCount,
        adSpend,
        adSales,
        totalVisits,
        refundCount,
        costPerUnit,
         totalSales,
         naturalOrders,
         totalCost,
         site: formSite,
        currency: siteOption.currency,
        note: formNote.trim(),
        createdAt: Date.now(),
      };
      addRecord(record);
      refreshRecords();
      toast.success('数据已录入');

      // 重置表单（日期保留今天）
      setFormOrders('');
      setFormListings('');
      setFormAdSpend('');
      setFormAdSales('');
      setFormVisits('');
      setFormRefunds('');
       setFormTotalSales('');
       setFormNaturalOrders('');
       setFormTotalCost('');
       setFormNote('');
    } finally {
      setIsSubmitting(false);
    }
  }

  function handleDelete(id: string) {
    if (!confirm('确定删除这条记录吗？')) return;
    deleteRecord(id);
    refreshRecords();
    toast.success('已删除');
  }

  const fmtPercent = (v: number) => (v * 100).toFixed(1);
  const fmtMoney = (v: number) => v.toFixed(2);

  return (
    <div className="space-y-5">
      {/* 标题区 */}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h1 className="text-xl font-bold flex items-center gap-2" style={{ color: theme.primaryDark }}>
            <Target className="size-5" style={{ color: theme.primary }} />
            KPI 驾驶舱
          </h1>
          <p className="text-xs text-muted-foreground mt-1">
            {nickname} · 每日业绩追踪与健康度预警
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Badge
            variant="outline"
            className="text-xs"
            style={{
              backgroundColor: todayStatus.overall.bg,
              borderColor: todayStatus.overall.color,
              color: todayStatus.overall.color,
            }}
          >
            <KpiStatusDot status={todayStatus.overall} />
            今日{todayStatus.overall.label}
          </Badge>
        </div>
      </div>

      {/* 今日零单红色预警横幅 */}
      {todayStatus.zeroOrder && (
        <div
          className="rounded-lg px-4 py-3 flex items-center gap-3"
          style={{
            backgroundColor: 'rgba(220,38,38,0.1)',
            border: '1px solid rgba(220,38,38,0.3)',
          }}
        >
          <AlertTriangle className="size-5 shrink-0 text-red-600" />
          <div>
            <div className="text-sm font-semibold text-red-700">今日零单</div>
            <div className="text-xs text-red-600">
              检查广告投放是否正常、流量是否掉了、listing 是否有异常
            </div>
          </div>
        </div>
      )}

      {/* 顶部 KPI 卡：今日 + 本月 */}
      <div className="space-y-3">
        <div className="flex items-center gap-2">
          <Calendar className="size-4" style={{ color: theme.primary }} />
          <span className="text-sm font-semibold" style={{ color: theme.primaryDark }}>
            今日概览
          </span>
          <span className="text-xs text-muted-foreground">{today}</span>
        </div>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          <KpiMetricCard
            label="今日出单"
            value={todayOrderCount}
            suffix="单"
            status={todayStatus.zeroOrder
              ? { level: 'red', label: '零单', color: '#dc2626', bg: 'rgba(220,38,38,0.1)' }
              : todayStatus.overall}
            icon={ShoppingCart}
            theme={theme}
            subLabel={`上架 ${todayRecords.reduce((s, r) => s + r.listingCount, 0)} 个`}
          />
          <KpiMetricCard
            label="今日 ACOS"
            value={fmtPercent(todayMetrics.acos)}
            suffix="%"
            status={todayStatus.acos}
            icon={DollarSign}
            theme={theme}
            subLabel={`广告花费 $${fmtMoney(todayMetrics.totalCost)}`}
          />
          <KpiMetricCard
            label="今日转化率"
            value={fmtPercent(todayMetrics.conversionRate)}
            suffix="%"
            status={todayStatus.conversion}
            icon={TrendingUp}
            theme={theme}
            subLabel={`访问 ${todayRecords.reduce((s, r) => s + r.totalVisits, 0).toLocaleString()}`}
          />
          <KpiMetricCard
            label="今日退款率"
            value={fmtPercent(todayMetrics.refundRate)}
            suffix="%"
            status={todayStatus.refund}
            icon={TrendingDown}
            theme={theme}
            subLabel={`退款 ${todayRecords.reduce((s, r) => s + r.refundCount, 0)} 单`}
          />
        </div>
      </div>

      <div className="space-y-3">
        <div className="flex items-center gap-2">
          <TrendingUp className="size-4" style={{ color: theme.primary }} />
          <span className="text-sm font-semibold" style={{ color: theme.primaryDark }}>
            本月汇总
          </span>
          <span className="text-xs text-muted-foreground">
            {monthRange.start} ~ {monthRange.end}
          </span>
        </div>
         <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3">
           <KpiMetricCard
             label="累计出单"
             value={monthOrderCount}
             suffix="单"
             status={monthOrderCount === 0
               ? { level: 'red', label: '零单', color: '#dc2626', bg: 'rgba(220,38,38,0.1)' }
               : monthStatus.overall}
             icon={ShoppingCart}
             theme={theme}
             subLabel={`累计上架 ${monthRecords.reduce((s, r) => s + r.listingCount, 0)} 个`}
           />
           <KpiMetricCard
             label="累计销售额"
             value={fmtMoney(monthMetrics.totalSales)}
             suffix={monthCurrency === 'MIX' ? '多币种' : monthCurrency}
             status={monthMetrics.totalSales > 0
               ? { level: 'green', label: '正常', color: '#16a34a', bg: 'rgba(22,163,74,0.1)' }
               : { level: 'red', label: '为0', color: '#dc2626', bg: 'rgba(220,38,38,0.1)' }}
             icon={DollarSign}
             theme={theme}
             subLabel={`ROI ${monthMetrics.roi >= 0 ? '+' : ''}${(monthMetrics.roi * 100).toFixed(0)}%`}
           />
           <KpiMetricCard
             label="月均 ACOS"
             value={fmtPercent(monthMetrics.acos)}
             suffix="%"
             status={monthStatus.acos}
             icon={Target}
             theme={theme}
             subLabel={`广告花费 ${monthCurrency === 'MIX' ? '' : monthCurrency + ' '}${fmtMoney(monthAdSpend)}`}
           />
           <KpiMetricCard
             label="月均 TACOS"
             value={fmtPercent(monthMetrics.tacos)}
             suffix="%"
             status={monthMetrics.tacos > 0.4
               ? { level: 'red', label: '过高', color: '#dc2626', bg: 'rgba(220,38,38,0.1)' }
               : monthMetrics.tacos > 0.25
                 ? { level: 'orange', label: '偏高', color: '#f59e0b', bg: 'rgba(245,158,11,0.1)' }
                 : { level: 'green', label: '健康', color: '#16a34a', bg: 'rgba(22,163,74,0.1)' }}
             icon={DollarSign}
             theme={theme}
             subLabel="广告/总销售额"
           />
           <KpiMetricCard
             label="自然单占比"
             value={fmtPercent(monthMetrics.naturalOrderRate)}
             suffix="%"
             status={monthMetrics.naturalOrderRate > 0.6
               ? { level: 'green', label: '健康', color: '#16a34a', bg: 'rgba(22,163,74,0.1)' }
               : monthMetrics.naturalOrderRate > 0.3
                 ? { level: 'orange', label: '一般', color: '#f59e0b', bg: 'rgba(245,158,11,0.1)' }
                 : { level: 'red', label: '偏低', color: '#dc2626', bg: 'rgba(220,38,38,0.1)' }}
             icon={TrendingUp}
             theme={theme}
             subLabel={`自然单 ${monthNaturalOrders} 单`}
           />
           <KpiMetricCard
             label="月均转化率"
             value={fmtPercent(monthMetrics.conversionRate)}
             suffix="%"
             status={monthStatus.conversion}
             icon={Eye}
             theme={theme}
             subLabel={`总访问 ${monthRecords.reduce((s, r) => s + r.totalVisits, 0).toLocaleString()}`}
           />
         </div>
      </div>

      {/* 趋势图 */}
      <CollapsibleSection
        title="趋势图表"
        subtitle="出单 / 销售额 / ACOS 变化趋势"
        theme={theme}
        expanded={expandedSections.chart}
        onToggle={() => toggleSection('chart')}
      >
        <div className="flex items-center justify-between mb-3">
          <div className="text-xs text-muted-foreground">
            近 {trendDays} 天数据
          </div>
          <div className="flex items-center gap-1">
            <Button
              size="sm"
              variant={activeView === '7d' ? 'default' : 'secondary'}
              className="h-7 text-xs"
              onClick={() => setActiveView('7d')}
            >
              7 天
            </Button>
            <Button
              size="sm"
              variant={activeView === '30d' ? 'default' : 'secondary'}
              className="h-7 text-xs"
              onClick={() => setActiveView('30d')}
            >
              30 天
            </Button>
          </div>
        </div>
        <Card
          className="border"
          style={{
            backgroundColor: theme.ui.glassBg,
            borderColor: theme.ui.cardBorder,
            boxShadow: theme.ui.glassShadow,
          }}
        >
          <CardContent className="pt-4 pb-2">
            {records.length === 0 ? (
              <div className="h-[300px] flex flex-col items-center justify-center text-muted-foreground">
                <TrendingUp className="size-10 mb-2 opacity-30" />
                <p className="text-sm">暂无数据，先录入今天的业绩吧～</p>
              </div>
            ) : (
              <ReactEChartsCore
                echarts={echarts}
                option={chartOption as EChartsOption}
                className="h-[300px] w-full"
                notMerge
                lazyUpdate
              />
            )}
          </CardContent>
        </Card>
      </CollapsibleSection>

      {/* 经营小结 */}
      <BusinessSummaryCard records={records} currency={currentCurrency} />

      {/* 大厂总监诊断提示词 */}
      <DirectorPromptCard
        theme={theme}
        expanded={expandedSections.director}
        onToggle={() => toggleSection('director')}
      />

      {/* 每日数据录入 */}
      <CollapsibleSection
        title="每日数据录入"
        subtitle="每天下班前花 1 分钟记录当天业绩"
        theme={theme}
        expanded={expandedSections.form}
        onToggle={() => toggleSection('form')}
      >
        <Card
          className="border"
          style={{
            backgroundColor: theme.ui.glassBg,
            borderColor: theme.ui.cardBorder,
            boxShadow: theme.ui.glassShadow,
          }}
        >
          <CardContent className="pt-4">
            <form onSubmit={handleSubmit} className="grid gap-3 grid-cols-2 md:grid-cols-4">
              <div className="space-y-1.5">
                <label className="text-xs font-medium text-foreground">日期</label>
                <Input
                  type="date"
                  value={formDate}
                  onChange={e => setFormDate(e.target.value)}
                  className="h-9 text-sm"
                />
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-medium text-foreground">出单数</label>
                <Input
                  type="number"
                  min="0"
                  placeholder="如 15"
                  value={formOrders}
                  onChange={e => setFormOrders(e.target.value)}
                  className="h-9 text-sm"
                />
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-medium text-foreground">自然单数</label>
                <Input
                  type="number"
                  min="0"
                  placeholder="如 8"
                  value={formNaturalOrders}
                  onChange={e => setFormNaturalOrders(e.target.value)}
                  className="h-9 text-sm"
                />
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-medium text-foreground">上架数</label>
                <Input
                  type="number"
                  min="0"
                  placeholder="如 3"
                  value={formListings}
                  onChange={e => setFormListings(e.target.value)}
                  className="h-9 text-sm"
                />
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-medium text-foreground">退款数</label>
                <Input
                  type="number"
                  min="0"
                  placeholder="如 1"
                  value={formRefunds}
                  onChange={e => setFormRefunds(e.target.value)}
                  className="h-9 text-sm"
                />
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-medium text-foreground">总访问量</label>
                <Input
                  type="number"
                  min="0"
                  placeholder="如 500"
                  value={formVisits}
                  onChange={e => setFormVisits(e.target.value)}
                  className="h-9 text-sm"
                />
              </div>
               <div className="space-y-1.5">
                 <label className="text-xs font-medium text-foreground">
                   广告花费 <span className="text-muted-foreground">({currentCurrency})</span>
                 </label>
                <Input
                  type="number"
                  min="0"
                  step="0.01"
                  placeholder="如 50.00"
                  value={formAdSpend}
                  onChange={e => setFormAdSpend(e.target.value)}
                  className="h-9 text-sm"
                />
              </div>
               <div className="space-y-1.5">
                 <label className="text-xs font-medium text-foreground">
                   广告销售额 <span className="text-muted-foreground">({currentCurrency})</span>
                 </label>
                <Input
                  type="number"
                  min="0"
                  step="0.01"
                  placeholder="如 200.00"
                  value={formAdSales}
                  onChange={e => setFormAdSales(e.target.value)}
                  className="h-9 text-sm"
                />
              </div>
               <div className="space-y-1.5">
                 <label className="text-xs font-medium text-foreground">
                   总销售额 <span className="text-muted-foreground">({currentCurrency})</span>
                 </label>
                <Input
                  type="number"
                  min="0"
                  step="0.01"
                  placeholder="如 350.00"
                  value={formTotalSales}
                  onChange={e => setFormTotalSales(e.target.value)}
                  className="h-9 text-sm"
                />
              </div>
               <div className="space-y-1.5">
                 <label className="text-xs font-medium text-foreground">
                   总成本费 <span className="text-muted-foreground">(CNY)</span>
                 </label>
                 <Input
                   type="number"
                   min="0"
                   step="0.01"
                   placeholder="如 800.00"
                   value={formTotalCost}
                   onChange={e => setFormTotalCost(e.target.value)}
                   className="h-9 text-sm"
                 />
               </div>
               <div className="space-y-1.5">
                 <label className="text-xs font-medium text-foreground">主要站点/币种</label>
                <Select value={formSite} onValueChange={setFormSite}>
                  <SelectTrigger className="h-9 text-sm">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {SITE_OPTIONS.map(opt => (
                      <SelectItem key={opt.value} value={opt.value} className="text-sm">
                        {opt.label} / {opt.currency}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="col-span-2 md:col-span-4 space-y-1.5">
                <label className="text-xs font-medium text-foreground">
                  今日特殊备忘 / 调整
                  <span className="text-muted-foreground font-normal"> · 月底复盘一目了然</span>
                </label>
                <Textarea
                  value={formNote}
                  onChange={e => setFormNote(e.target.value)}
                  placeholder="如：调整了核心词广告预算、遭遇恶意跟卖、提价2美金等…"
                  className="min-h-[64px] text-sm resize-y"
                />
              </div>
              <div className="col-span-2 md:col-span-4 flex items-center justify-between pt-1">
                <div className="text-xs text-muted-foreground">
                  数据保存在本地浏览器，按登录账号隔离
                </div>
                <Button
                  type="submit"
                  disabled={isSubmitting}
                  className="h-9 px-5"
                  style={{ backgroundColor: theme.primary }}
                >
                  <Plus className="size-4 mr-1" />
                  保存今日数据
                </Button>
              </div>
            </form>
          </CardContent>
        </Card>
      </CollapsibleSection>

      {/* 我的记录列表 */}
      <CollapsibleSection
        title="我的业绩记录"
        subtitle={`共 ${records.length} 条记录`}
        theme={theme}
        expanded={expandedSections.list}
        onToggle={() => toggleSection('list')}
      >
        <Card
          className="border overflow-hidden"
          style={{
            backgroundColor: theme.ui.glassBg,
            borderColor: theme.ui.cardBorder,
            boxShadow: theme.ui.glassShadow,
          }}
        >
          <div className="w-full overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr
                  style={{ backgroundColor: theme.primary + '0A' }}
                  className="text-xs text-muted-foreground"
                >
                  <th className="text-left px-3 py-2.5 font-medium whitespace-nowrap">日期</th>
                  <th className="text-right px-3 py-2.5 font-medium whitespace-nowrap">出单</th>
                  <th className="text-right px-3 py-2.5 font-medium whitespace-nowrap">销售额</th>
                  <th className="text-right px-3 py-2.5 font-medium whitespace-nowrap">ACOS</th>
                   <th className="text-right px-3 py-2.5 font-medium whitespace-nowrap">TACOS</th>
                   <th className="text-right px-3 py-2.5 font-medium whitespace-nowrap">转化率</th>
                   <th className="text-right px-3 py-2.5 font-medium whitespace-nowrap">退款率</th>
                   <th className="text-left px-3 py-2.5 font-medium whitespace-nowrap">站点</th>
                   <th className="text-left px-3 py-2.5 font-medium whitespace-nowrap min-w-[180px]">备忘</th>
                   <th className="text-center px-3 py-2.5 font-medium whitespace-nowrap">状态</th>
                   <th className="text-right px-3 py-2.5 font-medium whitespace-nowrap">操作</th>
                </tr>
              </thead>
              <tbody>
                {records.length === 0 ? (
                   <tr>
                     <td colSpan={11} className="text-center py-10 text-muted-foreground text-xs">
                       还没有记录，先在上方录入今天的数据吧
                     </td>
                   </tr>
                ) : (
                  records.map(record => {
                    const m = calculateKpiMetrics([record]);
                    const s = getKpiStatus(m, record.orderCount);
                    return (
                      <tr key={record.id} className="border-t" style={{ borderColor: theme.ui.cardBorder }}>
                        <td className="px-3 py-2.5 whitespace-nowrap tabular-nums">{record.date}</td>
                        <td className="px-3 py-2.5 text-right tabular-nums font-medium">
                          {record.orderCount}
                        </td>
                         <td className="px-3 py-2.5 text-right tabular-nums">
                           <span className="text-muted-foreground mr-1">{record.currency || 'USD'}</span>
                           {fmtMoney(m.totalSales)}
                         </td>
                         <td className="px-3 py-2.5 text-right tabular-nums">
                           <span style={{ color: s.acos.color }}>{fmtPercent(m.acos)}%</span>
                         </td>
                         <td className="px-3 py-2.5 text-right tabular-nums">
                           <span style={{ color: m.tacos > 0.3 ? '#dc2626' : m.tacos > 0.2 ? '#f59e0b' : '#16a34a' }}>
                             {fmtPercent(m.tacos)}%
                           </span>
                         </td>
                        <td className="px-3 py-2.5 text-right tabular-nums">
                          <span style={{ color: s.conversion.color }}>
                            {fmtPercent(m.conversionRate)}%
                          </span>
                        </td>
                         <td className="px-3 py-2.5 text-right tabular-nums">
                           <span style={{ color: s.refund.color }}>
                             {fmtPercent(m.refundRate)}%
                           </span>
                         </td>
                         <td className="px-3 py-2.5 text-left text-xs text-muted-foreground whitespace-nowrap">
                           {record.site ? SITE_OPTIONS.find(o => o.value === record.site)?.label || record.site : '—'}
                         </td>
                         <td className="px-3 py-2.5 text-left text-xs text-muted-foreground">
                           <span className="block truncate max-w-[240px]" title={record.note}>
                             {record.note || '—'}
                           </span>
                         </td>
                        <td className="px-3 py-2.5 text-center">
                          <div className="flex items-center justify-center gap-1.5">
                            <KpiStatusDot status={s.overall} />
                            <span className="text-xs" style={{ color: s.overall.color }}>
                              {s.zeroOrder ? '零单' : s.overall.label}
                            </span>
                          </div>
                        </td>
                        <td className="px-3 py-2.5 text-right">
                          <Button
                            variant="ghost"
                            size="sm"
                            className="h-7 w-7 p-0 text-muted-foreground hover:text-red-500"
                            onClick={() => handleDelete(record.id)}
                            aria-label="删除"
                          >
                            <Trash2 className="size-3.5" />
                          </Button>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
        </Card>
      </CollapsibleSection>
    </div>
  );
}
