import { useState, useRef, useEffect, type ReactElement } from 'react';
import { Copy, Check, Briefcase, Target, Layers, Zap, MessageSquareWarning } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { copyToClipboard } from '@lark-apaas/client-toolkit-lite';
import CollapsibleSection from '@/components/CollapsibleSection';
import type { ThemeConfig } from '@/lib/theme';

interface DirectorPromptCardProps {
  theme: ThemeConfig;
  expanded: boolean;
  onToggle: () => void;
}

// 完整提示词原文（用于复制，保留纯文本层级，一字不改）
const FULL_PROMPT_TEXT = `# Role
你现在是一位在深圳「坂田五虎、华南城四少、龙华十三狼、环球易购、安克创新、泽宝等龙头公司级别」大卖里历练出来的顶级跨境电商操盘手、运营总监。你手里经过的结余资金都是亿级的，管理过数百人的运营团队，极其擅长从宏观的资金周转、供应链博弈，到微观的单品ROI、广告打法、爆款打造全套流程。
# Task
请根据我接下来提供给你的【日报/周报/月报】数据与运营记录，站在跨境大厂核心操盘手的视角，帮我进行一次深度复盘。
# Output Style
1. 拒绝花里胡哨的理论，全部用跨境圈内最接底气的大白话、大实话来点评，一针见血，扒掉数据的美化外衣。
2. 说话要有大卖总监的格局和狠辣——不只看几单的得失，更看重资金回报率（ROI）、库存周转、和有没有给平台白打工。
# Format
请严格按照以下三个板块输出：
### 🎯 【大厂总监诊断：问题在哪？】
（请用最通俗的大白话，直接指出当前运营和数据中最致命的 2-3 个核心问题。不管是广告费打水漂、库存周转太慢、还是运营策略在做无用功，直接点出来。）
### 🛠️ 【总监拆解：怎么破局？】
（针对上述问题，给出具体、可落地、高效率的改良方法。别玩虚的，直接告诉我第一步动哪个链接、第二步怎么调广告竞价、第三步怎么控库存。）
### 💡 【商业底层清醒剂】
（从大卖的全局视角，针对我的资金链、账号安全或核心操盘思维，给出一句最能让人惊醒的商业提醒。）
---
【基本背景备忘】
- 我的主营品类/站点：[例如：美国站3C数码配件 / 欧洲站户外家居]
- 核心客单价：[例如：25-35美金]
- 目前团队最头疼的问题：[例如：流量高但不转化 / 广告费占比太高 / 销量大但没利润]
这是我目前的日报/周报/月报数据，请开始你的大厂级诊断：
[请在此处粘贴你的 日报/周报/月报 数据或运营记录]`;

// 占位符关键词（用于高亮）
const PLACEHOLDER_PATTERNS = [
  '[例如：美国站3C数码配件 / 欧洲站户外家居]',
  '[例如：25-35美金]',
  '[例如：流量高但不转化 / 广告费占比太高 / 销量大但没利润]',
  '[请在此处粘贴你的 日报/周报/月报 数据或运营记录]',
];

// 模块元信息
interface SectionMeta {
  key: string;
  title: string;
  icon: ReactElement;
  accent: string;
}

const SECTION_META: SectionMeta[] = [
  { key: 'Role', title: '角色设定', icon: <Briefcase className="size-4 shrink-0" />, accent: 'from-primary/15 to-primary/5' },
  { key: 'Task', title: '任务目标', icon: <Target className="size-4 shrink-0" />, accent: 'from-blue-500/15 to-blue-500/5' },
  { key: 'Output Style', title: '输出风格', icon: <MessageSquareWarning className="size-4 shrink-0" />, accent: 'from-amber-500/15 to-amber-500/5' },
  { key: 'Format', title: '输出格式', icon: <Layers className="size-4 shrink-0" />, accent: 'from-purple-500/15 to-purple-500/5' },
];

// 模块结构定义
interface ModuleBlock {
  title: string;
  rawTitle: string;
  body: string[];
  meta: SectionMeta;
  subsections: SubSection[];
}

interface SubSection {
  title: string;
  rawTitle: string;
  body: string[];
}

// 解析全文为模块结构
function parseModules(): ModuleBlock[] {
  const lines = FULL_PROMPT_TEXT.split('\n');
  const modules: ModuleBlock[] = [];
  let currentModule: ModuleBlock | null = null;
  let currentSub: SubSection | null = null;

  for (const line of lines) {
    if (line.startsWith('# ')) {
      const rawTitle = line.replace(/^#\s+/, '');
      const meta = SECTION_META.find((m) => rawTitle.startsWith(m.key)) ?? SECTION_META[0];
      if (currentModule && currentSub) {
        currentModule.subsections.push(currentSub);
        currentSub = null;
      }
      currentModule = { title: rawTitle, rawTitle, body: [], meta, subsections: [] };
      modules.push(currentModule);
    } else if (line.startsWith('### ')) {
      const subTitle = line.replace(/^###\s+/, '');
      if (currentModule) {
        if (currentSub) currentModule.subsections.push(currentSub);
        currentSub = { title: subTitle, rawTitle: subTitle, body: [] };
      }
    } else if (line.startsWith('## ')) {
      // 跳过二级，当作普通内容
      if (currentSub) {
        currentSub.body.push(line);
      } else if (currentModule) {
        currentModule.body.push(line);
      }
    } else {
      if (currentSub) {
        currentSub.body.push(line);
      } else if (currentModule) {
        currentModule.body.push(line);
      }
    }
  }
  if (currentModule && currentSub) currentModule.subsections.push(currentSub);
  return modules;
}

const MODULES = parseModules();

// 占位符高亮渲染
function Highlighted({ text }: { text: string }) {
  let result: (string | ReactElement)[] = [text];
  PLACEHOLDER_PATTERNS.forEach((ph) => {
    const next: (string | ReactElement)[] = [];
    result.forEach((chunk, ci) => {
      if (typeof chunk !== 'string') {
        next.push(chunk);
        return;
      }
      const parts = chunk.split(ph);
      parts.forEach((part, i) => {
        if (part) next.push(part);
        if (i < parts.length - 1) {
          next.push(
            <span
              key={`ph-${ph}-${ci}-${i}`}
              className="inline-block px-1.5 py-0.5 rounded-md bg-primary/10 text-primary font-semibold text-[0.85em] align-baseline break-words"
            >
              {ph}
            </span>,
          );
        }
      });
    });
    result = next;
  });
  return <>{result}</>;
}

// 渲染普通内容行
function renderContentLines(lines: string[]) {
  return lines.map((line, idx) => {
    const trimmed = line.trim();
    if (trimmed === '') return <div key={idx} className="h-1.5" />;
    // 编号行 1. / 2.
    if (/^\d+\.\s+/.test(trimmed)) {
      const match = trimmed.match(/^(\d+)\.\s+(.*)$/);
      const num = match?.[1] ?? '';
      const content = match?.[2] ?? trimmed;
      return (
        <div key={idx} className="flex gap-2 text-sm text-foreground/85 leading-relaxed">
          <span className="shrink-0 font-semibold text-primary text-xs mt-0.5 min-w-[1.25rem]">{num}.</span>
          <span className="flex-1 min-w-0">
            <Highlighted text={content} />
          </span>
        </div>
      );
    }
    // 分隔线 ---
    if (/^-{3,}$/.test(trimmed)) {
      return <div key={idx} className="my-2 border-t border-dashed border-border/60" />;
    }
    // 项目符号 -
    if (/^[-*]\s+/.test(trimmed)) {
      const content = trimmed.replace(/^[-*]\s+/, '');
      const indentLevel = (line.match(/^\s*/)?.[0].length ?? 0) >= 3 ? 1 : 0;
      return (
        <div key={idx} className={`flex gap-2 text-sm text-foreground/85 leading-relaxed ${indentLevel > 0 ? 'pl-4' : ''}`}>
          <span className="text-muted-foreground shrink-0 mt-1.5 size-1 rounded-full bg-muted-foreground/60" />
          <span className="flex-1 min-w-0">
            <Highlighted text={content} />
          </span>
        </div>
      );
    }
    // 普通段落
    return (
      <p key={idx} className="text-sm text-foreground/85 leading-relaxed">
        <Highlighted text={trimmed} />
      </p>
    );
  });
}

// 单个模块卡片
function ModuleCard({ mod }: { mod: ModuleBlock }) {
  const isFormat = mod.meta.key === 'Format';
  const isRole = mod.meta.key === 'Role';
  const isStyle = mod.meta.key === 'Output Style';
  const isTask = mod.meta.key === 'Task';

  return (
    <div className="rounded-xl border border-border/60 bg-card/80 overflow-hidden shadow-sm">
      {/* 模块标题条 */}
      <div className={`flex items-center gap-2 px-3.5 py-2.5 bg-gradient-to-r ${mod.meta.accent} border-b border-border/40`}>
        <span className="text-primary">{mod.meta.icon}</span>
        <div className="flex-1 min-w-0">
          <div className="text-sm font-semibold text-foreground truncate">
            <Highlighted text={mod.title} />
          </div>
        </div>
        <Badge variant="outline" className="text-[10px] font-medium text-muted-foreground shrink-0 h-5">
          {mod.meta.title}
        </Badge>
      </div>

      {/* 模块内容 */}
      <div className="p-3.5 space-y-2">
        {!isFormat && mod.body.length > 0 && (
          <div className="space-y-1.5">
            {renderContentLines(mod.body)}
          </div>
        )}

        {/* Role 模块加个风格标签 */}
        {isRole && (
          <div className="mt-2 flex flex-wrap gap-1.5">
            <Badge variant="secondary" className="text-[10px]">坂田五虎级·华南城四少</Badge>
            <Badge variant="secondary" className="text-[10px]">亿级操盘</Badge>
            <Badge variant="secondary" className="text-[10px]">总监视角</Badge>
          </div>
        )}

        {/* Output Style 用编号卡片 */}
        {isStyle && mod.body.length > 0 && (
          <div className="space-y-2">
            {mod.body.filter((l) => /^\d+\.\s+/.test(l.trim())).map((line, idx) => {
              const trimmed = line.trim();
              const match = trimmed.match(/^(\d+)\.\s+(.*)$/);
              const num = match?.[1] ?? '';
              const content = match?.[2] ?? trimmed;
              return (
                <div key={idx} className="flex gap-2.5 rounded-lg border border-border/50 bg-background/40 p-2.5">
                  <div className="shrink-0 size-6 rounded-full bg-amber-500/15 text-amber-600 dark:text-amber-400 text-xs font-bold flex items-center justify-center">
                    {num}
                  </div>
                  <div className="flex-1 min-w-0 pt-0.5">
                    <Highlighted text={content} />
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {/* Format 三个子板块 */}
        {isFormat && (
          <div className="space-y-3">
            {/* 背景备忘 */}
            {mod.body.length > 0 && (
              <div className="space-y-1.5">
                {renderContentLines(mod.body)}
              </div>
            )}
            {/* 三个子板块 */}
            {mod.subsections.map((sub, sIdx) => {
              const iconColors = ['bg-rose-500', 'bg-emerald-500', 'bg-violet-500'];
              const iconBgColors = ['bg-rose-500/10 text-rose-600 dark:text-rose-400', 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400', 'bg-violet-500/10 text-violet-600 dark:text-violet-400'];
              return (
                <div key={sIdx} className="rounded-lg border border-border/50 bg-background/40 overflow-hidden">
                  <div className="px-3 py-2 bg-muted/40 border-b border-border/40 flex items-center gap-2">
                    <span className={`size-5 shrink-0 rounded-md flex items-center justify-center text-[10px] font-bold ${iconBgColors[sIdx % 3]}`}>
                      {sIdx + 1}
                    </span>
                    <div className="text-sm font-semibold text-foreground">
                      <Highlighted text={sub.title} />
                    </div>
                  </div>
                  <div className="p-3">
                    {sub.body.length > 0 && (
                      <div className="text-xs text-muted-foreground italic leading-relaxed">
                        {sub.body.filter((l) => l.trim()).map((l, i) => (
                          <p key={i} className="first:mt-0 mt-1">
                            {l.trim().replace(/^[（(]/, '').replace(/[）)]$/, '')}
                          </p>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

// 主提示词内容
function PromptContent() {
  return (
    <div className="space-y-3">
      {MODULES.map((mod, idx) => (
        <ModuleCard key={idx} mod={mod} />
      ))}
    </div>
  );
}

export default function DirectorPromptCard({ theme, expanded, onToggle }: DirectorPromptCardProps) {
  const [copied, setCopied] = useState(false);
  const copyTimerRef = useRef<number | null>(null);

  // 清理复制状态定时器，避免卸载后 setState
  useEffect(() => {
    return () => {
      if (copyTimerRef.current) {
        clearTimeout(copyTimerRef.current);
        copyTimerRef.current = null;
      }
    };
  }, []);

  async function handleCopy(e: React.MouseEvent) {
    e.stopPropagation();
    try {
      await copyToClipboard(FULL_PROMPT_TEXT);
      setCopied(true);
      toast.success('已复制到剪贴板');
      if (copyTimerRef.current) clearTimeout(copyTimerRef.current);
      copyTimerRef.current = window.setTimeout(() => setCopied(false), 2000);
    } catch {
      toast.error('复制失败，请手动选择复制');
    }
  }

  return (
    <CollapsibleSection
      title="日报/周报/月报诊断提示词"
      subtitle="坂田五虎、华南城四少、龙华十三狼等龙头公司级别操盘手视角 · 深度复盘"
      summary="一键复制，粘贴到AI对话框直接使用"
      icon={<Zap className="size-5" />}
      badge="经营复盘提示词"
      badgeColor="warning"
      theme={theme}
      expanded={expanded}
      onToggle={onToggle}
      className="!shadow-none !border-0"
      headerExtra={
        <Button
          size="sm"
          variant="secondary"
          onClick={handleCopy}
          className="h-7 text-xs gap-1"
        >
          {copied ? (
            <>
              <Check className="size-3.5" />
              已复制
            </>
          ) : (
            <>
              <Copy className="size-3.5" />
              一键复制
            </>
          )}
        </Button>
      }
    >
      <div className="rounded-lg border border-border/50 bg-card/30 p-3 sm:p-4 max-h-[650px] overflow-y-auto">
        <PromptContent />
      </div>
      <div className="mt-3 flex items-center justify-between text-xs text-muted-foreground">
        <span>共 {FULL_PROMPT_TEXT.length} 字 · 四大模块结构化提示词</span>
        <Badge variant="outline" className="text-[10px] font-normal">
          总监复盘
        </Badge>
      </div>
    </CollapsibleSection>
  );
}
