import { useState, useMemo, useCallback, useRef, useEffect } from 'react';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Button } from '@/components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  TrendingUp,
  AlertTriangle,
  CheckCircle2,
  Info,
  AlertCircle,
  BarChart3,
  FileText,
  Copy,
  CheckCheck,
  ScrollText,
  Zap,
  Target,
  DollarSign,
  ShoppingCart,
  RotateCcw,
  ClipboardList,
   Sparkles,
   Wallet,
 } from 'lucide-react';
import { generateBusinessSummary, generateBusinessReport, type SummaryInsight, type BusinessReport, type BusinessReportSection } from '@/data/business-summary';
import type { IKpiDailyRecord } from '@/data/kpi';
import { toast } from 'sonner';
import { fetchWithCache, DEFAULT_TTL } from '@/lib/cache';
import { logger } from '@lark-apaas/client-toolkit-lite';
import { copyToClipboard } from '@lark-apaas/client-toolkit-lite';

interface BusinessSummaryCardProps {
  records: IKpiDailyRecord[];
  currency: string;
}

function InsightIcon({ level }: { level: SummaryInsight['level'] }) {
  switch (level) {
    case 'good':
      return <CheckCircle2 className="size-4 shrink-0 text-emerald-500" />;
    case 'warn':
      return <AlertTriangle className="size-4 shrink-0 text-amber-500" />;
    case 'danger':
      return <AlertCircle className="size-4 shrink-0 text-destructive" />;
    default:
      return <Info className="size-4 shrink-0 text-muted-foreground" />;
  }
}

function sectionIcon(key: string) {
  switch (key) {
    case 'link-health': return <Target className="size-4 shrink-0" />;
    case 'ad-efficiency': return <Zap className="size-4 shrink-0" />;
    case 'conversion': return <TrendingUp className="size-4 shrink-0" />;
    case 'profit-structure': return <DollarSign className="size-4 shrink-0" />;
    case 'gross-profit': return <Wallet className="size-4 shrink-0" />;
    case 'order-pace': return <ShoppingCart className="size-4 shrink-0" />;
    case 'refund': return <RotateCcw className="size-4 shrink-0" />;
    case 'memo-linkage': return <ClipboardList className="size-4 shrink-0" />;
    default: return <Info className="size-4 shrink-0" />;
  }
}

function levelBg(level: SummaryInsight['level']) {
  switch (level) {
    case 'good': return 'bg-emerald-50 border-emerald-200 text-emerald-900';
    case 'warn': return 'bg-amber-50 border-amber-200 text-amber-900';
    case 'danger': return 'bg-red-50 border-red-200 text-red-900';
    default: return 'bg-muted/50 border-border text-foreground';
  }
}

function sectionLevelBg(level: BusinessReportSection['level']) {
  switch (level) {
    case 'good': return 'border-l-emerald-500 bg-emerald-50/50';
    case 'warn': return 'border-l-amber-500 bg-amber-50/50';
    case 'danger': return 'border-l-red-500 bg-red-50/50';
    default: return 'border-l-muted-foreground bg-muted/30';
  }
}

function fmtMoney(v: number, currency: string): string {
  const symbol = currency === 'CNY' || currency === 'RMB' ? '¥' :
    currency === 'USD' ? '$' :
    currency === 'JPY' ? '¥' :
    currency === 'EUR' ? '€' :
    currency === 'GBP' ? '£' :
    currency === 'CAD' ? 'C$' :
    currency === 'AUD' ? 'A$' :
    currency === 'THB' ? '฿' :
    currency === 'MYR' ? 'RM' :
    currency === 'MXN' ? 'Mex$' : '';
  return `${symbol}${v.toLocaleString('zh-CN', { maximumFractionDigits: 2 })}`;
}

export default function BusinessSummaryCard({ records, currency }: BusinessSummaryCardProps) {
  const [period, setPeriod] = useState<'day' | 'week' | 'month'>('week');
  const [reportOpen, setReportOpen] = useState(false);
  const [report, setReport] = useState<BusinessReport | null>(null);
  const [copied, setCopied] = useState(false);
  const copyTimerRef = useRef<number | null>(null);

  // 清理复制状态定时器，避免卸载后 setState
  useEffect(() => {
    return () => {
      if (copyTimerRef.current) {
        clearTimeout(copyTimerRef.current);
        copyTimerRef.current = null;
      }
    };
  }, []);
  const [generating, setGenerating] = useState(false);

  const summary = useMemo(
    () => generateBusinessSummary(records, period),
    [records, period],
  );

  const { metrics, insights, hasData, rangeLabel, totalRecords, memoRecords } = summary;

  const handleGenerateReport = useCallback(async () => {
    setGenerating(true);
    try {
      // 获取汇率（带缓存）
      let exchangeRate: { rate: number; updatedAt: string; source: 'api' | 'fallback' | 'error' | 'none' } | null = null;
      try {
        const result = await fetchWithCache<any>('exchange-rates:all', '/exchange-rates', {
          ttl: DEFAULT_TTL,
          force: false,
        });
        const raw: any = result.data;
        const rates = raw?.data?.rates || raw?.rates || raw;
        const updatedAt = raw?.data?.updated || raw?.updated;
        const src = raw?.data?.source || raw?.source || 'api';
        if (rates && rates[currency] && Number(rates[currency]) > 0) {
          const rate = Number(rates[currency]);
          let d: Date;
          if (updatedAt) {
            d = new Date(updatedAt);
            if (isNaN(d.getTime())) d = new Date(result.timestamp);
          } else {
            d = new Date(result.timestamp);
          }
          const hh = String(d.getHours()).padStart(2, '0');
          const mm = String(d.getMinutes()).padStart(2, '0');
          exchangeRate = {
            rate: Number(rate.toFixed(4)),
            updatedAt: `${hh}:${mm}`,
            source: src === 'fallback' ? 'fallback' : 'api',
          };
        }
      } catch (err) {
        logger.warn('获取汇率失败:', String(err));
        // 汇率获取失败时用兜底值并标记 error
        const fallbackRates: Record<string, number> = { USD: 7.2, CAD: 5.3, AUD: 4.7, JPY: 0.048, THB: 0.2, MYR: 1.6, MXN: 0.4 };
        const fallbackRate = fallbackRates[currency] || 7.2;
        exchangeRate = {
          rate: fallbackRate,
          updatedAt: '参考值',
          source: 'error',
        };
      }
      const r = generateBusinessReport(records, period, currency, new Date(), exchangeRate);
      setReport(r);
      setReportOpen(true);
    } finally {
      setGenerating(false);
    }
  }, [records, period, currency]);

  const handleCopy = useCallback(async () => {
    if (!report) return;
    try {
      await copyToClipboard(report.text);
      setCopied(true);
      toast.success('已复制到剪贴板，直接粘贴发给主管');
      if (copyTimerRef.current) clearTimeout(copyTimerRef.current);
      copyTimerRef.current = window.setTimeout(() => setCopied(false), 2000);
    } catch {
      toast.error('复制失败，请手动选中复制');
    }
  }, [report]);

  return (
    <>
      <Card className="border border-border/60 shadow-sm">
        <CardHeader className="flex flex-row items-center justify-between pb-3">
          <div className="flex items-center gap-2">
            <BarChart3 className="size-5 text-primary" />
            <CardTitle className="text-base font-semibold">经营小结 · 让数据开口说话</CardTitle>
          </div>
          <div className="flex items-center gap-2">
            <Tabs
              value={period}
              onValueChange={(v) => setPeriod(v as 'day' | 'week' | 'month')}
              className="w-auto"
            >
              <TabsList className="h-8">
                <TabsTrigger value="day" className="text-xs h-7 px-3">日报</TabsTrigger>
                <TabsTrigger value="week" className="text-xs h-7 px-3">周报</TabsTrigger>
                <TabsTrigger value="month" className="text-xs h-7 px-3">月报</TabsTrigger>
              </TabsList>
            </Tabs>
             <Button
               size="sm"
               className="h-8"
               onClick={handleGenerateReport}
               disabled={generating}
             >
               <Sparkles className={`size-3.5 mr-1.5 ${generating ? 'animate-spin' : ''}`} />
               {generating ? '生成中...' : `生成${period === 'day' ? '日报' : period === 'week' ? '周报' : '月报'}`}
             </Button>
          </div>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center justify-between text-xs text-muted-foreground">
            <span>统计区间：{rangeLabel}</span>
                <span>录入 {totalRecords} {period === 'day' ? '' : '天'}</span>
          </div>

          {/* 关键数字 */}
          {hasData && (
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
              <div className="rounded-lg border border-border/60 bg-card p-3">
                <div className="text-xs text-muted-foreground mb-1">累计出单</div>
                <div className="text-lg font-bold text-foreground tabular-nums">{metrics.totalOrders}</div>
                <div className="text-[11px] text-muted-foreground">单</div>
              </div>
              <div className="rounded-lg border border-border/60 bg-card p-3">
                <div className="text-xs text-muted-foreground mb-1">广告花费</div>
                <div className="text-lg font-bold text-foreground tabular-nums">{fmtMoney(metrics.totalAdSpend, currency)}</div>
                <div className="text-[11px] text-muted-foreground">随币种切换</div>
              </div>
              <div className="rounded-lg border border-border/60 bg-card p-3">
                <div className="text-xs text-muted-foreground mb-1">总销售额</div>
                <div className="text-lg font-bold text-foreground tabular-nums">{fmtMoney(metrics.totalSales, currency)}</div>
                <div className="text-[11px] text-muted-foreground">随币种切换</div>
              </div>
              <div className="rounded-lg border border-border/60 bg-card p-3">
                <div className="text-xs text-muted-foreground mb-1">总成本费</div>
                <div className="text-lg font-bold text-foreground tabular-nums">¥{metrics.totalCostCNY.toFixed(0)}</div>
                <div className="text-[11px] text-muted-foreground">人民币 · 固定</div>
              </div>
            </div>
          )}

          {/* 结论列表 */}
          <div className="space-y-2">
            {insights.map((ins, i) => (
              <div
                key={i}
                className={`rounded-lg border p-3 ${levelBg(ins.level)}`}
              >
                <div className="flex items-start gap-2.5">
                  <InsightIcon level={ins.level} />
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between gap-2">
                      <span className="text-sm font-medium">{ins.title}</span>
                      {ins.value && (
                        <Badge variant="outline" className="shrink-0 text-[11px] h-5">
                          {ins.value}
                        </Badge>
                      )}
                    </div>
                    <p className="text-xs mt-1 opacity-80 leading-relaxed">{ins.detail}</p>
                  </div>
                </div>
              </div>
            ))}
          </div>

          {/* 备忘录大事记（如果有） */}
          {hasData && memoRecords.length > 0 && (
            <div className="pt-2 border-t border-border/50">
              <div className="text-xs font-medium text-foreground mb-2 flex items-center gap-1.5">
                <ScrollText className="size-3.5 text-primary" />
                备忘录大事记（{memoRecords.length} 条）
              </div>
              <div className="space-y-1.5 max-h-32 overflow-y-auto">
                {memoRecords.slice(0, 5).map((m, i) => (
                  <div key={i} className="text-xs text-muted-foreground flex gap-2">
                    <span className="shrink-0 tabular-nums">{m.date.slice(5)}</span>
                    <span className="truncate">{m.note}</span>
                  </div>
                ))}
                {memoRecords.length > 5 && (
                  <div className="text-[11px] text-muted-foreground">
                    还有 {memoRecords.length - 5} 条…
                  </div>
                )}
              </div>
            </div>
          )}

          {hasData && (
            <div className="grid grid-cols-3 gap-2 pt-2 border-t border-border/50">
              <div className="text-center">
                <div className="text-[11px] text-muted-foreground">ACOS</div>
                <div className={`text-sm font-semibold tabular-nums ${metrics.acos > 0.4 ? 'text-destructive' : metrics.acos > 0.25 ? 'text-amber-600' : 'text-emerald-600'}`}>
                  {(metrics.acos * 100).toFixed(1)}%
                </div>
              </div>
              <div className="text-center">
                <div className="text-[11px] text-muted-foreground">转化率</div>
                <div className={`text-sm font-semibold tabular-nums ${metrics.conversionRate < 0.05 ? 'text-destructive' : metrics.conversionRate < 0.08 ? 'text-amber-600' : 'text-emerald-600'}`}>
                  {metrics.conversionRate > 0 ? `${(metrics.conversionRate * 100).toFixed(1)}%` : '—'}
                </div>
              </div>
              <div className="text-center">
                <div className="text-[11px] text-muted-foreground">退款率</div>
                <div className={`text-sm font-semibold tabular-nums ${metrics.refundRate > 0.08 ? 'text-destructive' : metrics.refundRate > 0.05 ? 'text-amber-600' : 'text-emerald-600'}`}>
                  {(metrics.refundRate * 100).toFixed(1)}%
                </div>
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      {/* 报告弹窗 */}
      <Dialog open={reportOpen} onOpenChange={setReportOpen}>
        <DialogContent className="max-w-2xl max-h-[90vh] flex flex-col p-0">
          {/* 顶部标题区（固定） */}
          <div className="px-6 py-4 border-b border-border bg-gradient-to-r from-primary/5 via-background to-secondary/10 shrink-0">
            <DialogHeader>
              <DialogTitle className="flex items-center gap-2 text-lg">
                <Sparkles className="size-5 text-primary" />
                {report?.title || '经营报告'}
              </DialogTitle>
              <DialogDescription className="mt-1">
                {report?.rangeLabel} · 录入 {report?.totalRecords} 天
              </DialogDescription>
            </DialogHeader>
            {/* 一句话总评 */}
            {report?.hasData && report.overallComment && (
              <div className="mt-3 rounded-lg border border-border/60 bg-card/80 px-3 py-2 text-sm">
                <span className="font-semibold text-foreground">总评：</span>
                <span className="text-foreground/80">{report.overallComment.replace(/^[\u{1F534}\u{1F7E0}\u{1F7E1}\u{1F7E2}] /u, '')}</span>
              </div>
            )}
          </div>

          {/* 可滚动内容区 */}
          <div className="flex-1 overflow-y-auto px-6 py-4">
            {report && report.hasData && (
              <div className="space-y-5">
                {/* 1. 核心数据速览 */}
                <div>
                  <h4 className="text-sm font-bold mb-2.5 flex items-center gap-1.5 text-foreground">
                    <BarChart3 className="size-4 text-primary" />
                    一、核心数据速览
                  </h4>
                  <div className="grid grid-cols-3 gap-2">
                    {report.coreData.map((item, i) => {
                      const isProfit = item.highlight === 'profit';
                      const isLoss = item.highlight === 'loss';
                      const trendIcon = item.trend?.direction === 'up' ? '⬆️' : item.trend?.direction === 'down' ? '⬇️' : item.trend?.direction === 'flat' ? '➖' : '';
                      const trendColor = item.trend?.direction === 'up' ? 'text-emerald-600' : item.trend?.direction === 'down' ? 'text-red-600' : 'text-muted-foreground';
                      return (
                        <div
                          key={i}
                          className={`rounded-md border p-2.5 ${isProfit ? 'border-emerald-200 bg-emerald-50/60' : isLoss ? 'border-red-200 bg-red-50/60' : 'border-border/60 bg-card'}`}
                        >
                          <div className="text-[11px] text-muted-foreground">{item.label}</div>
                          <div className={`text-sm font-bold tabular-nums mt-0.5 ${isProfit ? 'text-emerald-700' : isLoss ? 'text-red-700' : 'text-foreground'}`}>
                            {item.value}
                          </div>
                          {item.trend && item.trend.direction !== 'none' && (
                            <div className={`text-[10px] mt-1 ${trendColor} font-medium`} title={item.trend.detail}>
                              {trendIcon} {item.trend.pct}
                            </div>
                          )}
                          {item.trend && item.trend.direction === 'none' && (
                            <div className="text-[10px] mt-1 text-muted-foreground/70">{item.trend.detail}</div>
                          )}
                          {item.note && (
                            <div className="text-[10px] text-muted-foreground opacity-70 mt-0.5">{item.note}</div>
                          )}
                        </div>
                      );
                    })}
                  </div>
                  {report.exchangeRate && report.exchangeRate.rate > 0 && (
                    <div className="mt-2 text-[11px] text-muted-foreground text-right">
                      汇率：1 {report.exchangeRate.currency} = {report.exchangeRate.rate.toFixed(2)} CNY
                      （{report.exchangeRate.source === 'api' ? '实时' : report.exchangeRate.source === 'fallback' ? '最近缓存' : '参考'}，{report.exchangeRate.updatedAt}）
                    </div>
                  )}
                  {report.exchangeRate && report.exchangeRate.source === 'error' && (
                    <div className="mt-2 text-[11px] text-amber-600 text-right">
                      汇率获取失败，按最近汇率 {report.exchangeRate.rate.toFixed(2)} 计算
                    </div>
                  )}
                </div>

                {/* 2. 犀利经营结论 */}
                {report.sections.length > 0 && (
                  <div>
                    <h4 className="text-sm font-bold mb-2.5 flex items-center gap-1.5 text-foreground">
                      <Zap className="size-4 text-primary" />
                      二、犀利经营结论
                    </h4>
                    <div className="space-y-3">
                      {report.sections.map((sec) => (
                        <div
                          key={sec.key}
                          className={`rounded-md border border-l-4 border-border/60 p-3 ${sectionLevelBg(sec.level)}`}
                        >
                          <div className="flex items-center gap-2 mb-2">
                            {sectionIcon(sec.key)}
                            <span className="text-sm font-bold text-foreground">{sec.title}</span>
                            <Badge
                              variant="outline"
                              className={`ml-auto text-[10px] h-5 ${
                                sec.level === 'danger' ? 'text-red-700 border-red-300 bg-red-100/50' :
                                sec.level === 'warn' ? 'text-amber-700 border-amber-300 bg-amber-100/50' :
                                sec.level === 'good' ? 'text-emerald-700 border-emerald-300 bg-emerald-100/50' :
                                ''
                              }`}
                            >
                              {sec.level === 'danger' ? '🔴 红警' : sec.level === 'warn' ? '🟠 橙警' : sec.level === 'good' ? '✅ 良好' : 'ℹ️ 信息'}
                            </Badge>
                          </div>
                           <div className="space-y-1.5 text-xs">
                             <div className="flex gap-2">
                               <span className="shrink-0 font-semibold text-foreground/70 w-10">现象</span>
                               <span className="text-foreground/90 leading-relaxed">{sec.phenomenon}</span>
                             </div>
                             <div className="flex gap-2">
                               <span className="shrink-0 font-semibold text-foreground/70 w-10">归因</span>
                               <span className="text-foreground/90 leading-relaxed whitespace-pre-line">{sec.attribution}</span>
                             </div>
                             <div className="flex gap-2">
                               <span className="shrink-0 font-semibold text-primary w-10">动作</span>
                               <span className="text-foreground/90 leading-relaxed whitespace-pre-line">{sec.action}</span>
                             </div>
                             {sec.plainPointer && (
                               <div className="mt-1.5 rounded-md bg-gradient-to-r from-primary/10 via-amber-50/60 to-primary/5 border border-primary/20 px-2.5 py-2">
                                 <span className="text-[11px] font-bold text-primary">👉 白话指针</span>
                                 <p className="text-xs text-foreground/90 leading-relaxed mt-0.5 whitespace-pre-line">{sec.plainPointer}</p>
                               </div>
                             )}
                           </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* 3. 行动清单 */}
                {report.actionList.length > 0 && (
                  <div>
                    <h4 className="text-sm font-bold mb-2.5 flex items-center gap-1.5 text-foreground">
                      <Target className="size-4 text-primary" />
                      三、{period === 'day' ? '明日' : period === 'week' ? '下周' : '下月'}行动清单 TOP{report.actionList.length}
                    </h4>
                    <div className="rounded-md border border-border/60 bg-card divide-y divide-border/60">
                      {report.actionList.map((a, i) => (
                        <div key={i} className="flex items-start gap-3 p-3">
                          <div className={`shrink-0 size-6 rounded-full flex items-center justify-center text-[11px] font-bold ${
                            a.priority === 1 ? 'bg-red-100 text-red-700' :
                            a.priority === 2 ? 'bg-amber-100 text-amber-700' :
                            'bg-emerald-100 text-emerald-700'
                          }`}>
                            {i + 1}
                          </div>
                          <div className="flex-1 text-sm text-foreground leading-relaxed pt-0.5">
                            {a.text}
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* 4. 备忘录大事记 */}
                {report.memoEvents.length > 0 && (
                  <div>
                    <h4 className="text-sm font-bold mb-2.5 flex items-center gap-1.5 text-foreground">
                      <ScrollText className="size-4 text-primary" />
                      四、备忘录大事记
                    </h4>
                    <div className="space-y-1.5 rounded-md border border-border/60 p-3 bg-card">
                      {report.memoEvents.map((m, i) => (
                        <div key={i} className="text-xs flex gap-3">
                          <span className="shrink-0 tabular-nums text-muted-foreground font-mono w-20">{m.date}</span>
                          <span className="text-foreground/90 leading-relaxed flex-1">{m.note}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* 5. 纯文本预览 */}
                <div>
                  <h4 className="text-sm font-bold mb-2.5 flex items-center gap-1.5 text-foreground">
                    <FileText className="size-4 text-primary" />
                    五、文本预览（一键复制发主管）
                  </h4>
                  <pre className="text-xs bg-muted/40 border border-border/60 rounded-md p-3 whitespace-pre-wrap font-mono leading-relaxed text-foreground/80 max-h-72 overflow-y-auto">
{report.text}
                  </pre>
                </div>
              </div>
            )}

            {report && !report.hasData && (
              <div className="py-12 text-center">
                <FileText className="size-12 mx-auto text-muted-foreground/30 mb-3" />
                <p className="text-muted-foreground text-sm">本周期暂无KPI数据</p>
                <p className="text-xs text-muted-foreground/70 mt-1">先录入几天数据再来生成报告</p>
              </div>
            )}
          </div>

          {/* 底部按钮（固定） */}
          <DialogFooter className="px-6 py-3 border-t border-border bg-card/50 shrink-0 flex gap-2">
            <Button variant="secondary" onClick={() => setReportOpen(false)}>
              关闭
            </Button>
            <Button onClick={handleCopy} disabled={!report?.hasData} className="min-w-[120px]">
              {copied ? (
                <><CheckCheck className="size-4 mr-1.5" />已复制</>
              ) : (
                <><Copy className="size-4 mr-1.5" />一键复制</>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}
